using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static partial class MiamiClothingBuild {
static void RoofBeam(G g,Vector3 a,Vector3 b,float width){int start=g.p.Count;Vector3 c=(a+b)*.5f;g.Box(c,new Vector3(width,Vector3.Distance(a,b),width),7);var q=Quaternion.FromToRotation(Vector3.up,(b-a).normalized);for(int i=start;i<g.p.Count;i++)g.p[i]=c+q*(g.p[i]-c);}
static void RoofText(G g,string text,Vector3 c,float height,bool red,bool near){int start=g.p.Count;GunLetter(g,text,c,height,red,near);for(int i=start;i<g.p.Count;i++){var p=g.p[i];p.z=c.z+(p.z-c.z)*.35f;g.p[i]=p;}}
static void GunRooftop(G g,float w,float d,float h,int lod){float z=d/2-1.2f;bool near=lod==0;RoofText(g,lod==2?"ROOF_TITLE_FAR":"ROOF_TITLE",new Vector3(0,h+2.5f,z),2.05f,false,near);RoofText(g,lod==2?"ROOF_SUBTITLE_FAR":"ROOF_SUBTITLE",new Vector3(0,h+.80f,z),.80f,true,near);
// Slim mounting rails behind the letter baselines; open installation, no solid backing.
g.Box(new Vector3(0,h+1.45f,z-.11f),new Vector3(15.1f,.065f,.09f),7);g.Box(new Vector3(0,h+.38f,z-.11f),new Vector3(12.45f,.055f,.08f),7);
foreach(float x in new[]{-6f,-3f,0,3f,6f}){g.Box(new Vector3(x,h+.76f,z-.15f),new Vector3(.075f,1.52f,.075f),7);g.Box(new Vector3(x,h+.04f,z-.15f),new Vector3(.36f,.08f,.48f),7);if(near){foreach(float dx in new[]{-.12f,.12f})g.Box(new Vector3(x+dx,h+.089f,z-.15f),new Vector3(.035f,.018f,.035f),0);}}
if(lod<2)foreach(float x in new[]{-6f,0,6f}){RoofBeam(g,new Vector3(x,h+.08f,z-1.05f),new Vector3(x,h+1.44f,z-.18f),.065f);g.Box(new Vector3(x,h+.04f,z-1.05f),new Vector3(.28f,.08f,.35f),7);}
}
static void AddGunRooftop(){var sc=SceneManager.GetActiveScene();var root=sc.GetRootGameObjects().Single(g=>g.name=="Gangfire Weapon Shop");var collider=root.GetComponent<BoxCollider>();float w=collider.size.x,d=collider.size.z+1,h=collider.size.y;string backup="FinalEnvironmentRoadBackup/BeforeGangfireRoof";Directory.CreateDirectory(backup);if(!File.Exists(backup+"/Scene.unity"))EditorSceneManager.SaveScene(sc,backup+"/Scene.unity",true);words=JsonUtility.FromJson<Words>(File.ReadAllText("FinalEnvironmentRoadReview/GangfireArt/Contours.json"));var roofWords=JsonUtility.FromJson<Words>(File.ReadAllText("FinalEnvironmentRoadReview/GangfireArt/RoofContours.json"));words.words=words.words.Concat(roofWords.words).ToArray();var totals=new int[3];var additions=new int[3];var atlasBytes=File.ReadAllBytes(Atlas);var filters=root.GetComponentsInChildren<MeshFilter>(true);
for(int lod=0;lod<3;lod++){var filter=filters.Single(f=>f.name=="Single mesh LOD"+lod);var current=filter.sharedMesh;string basePath=backup+"/LOD"+lod+".asset";if(!File.Exists(basePath)){var saved=UnityEngine.Object.Instantiate(current);UnityEditorInternal.InternalEditorUtility.SaveToSerializedFileAndForget(new UnityEngine.Object[]{saved},basePath,true);UnityEngine.Object.DestroyImmediate(saved);}var loaded=UnityEditorInternal.InternalEditorUtility.LoadSerializedFileAndForget(basePath);var source=loaded.OfType<Mesh>().Single();var g=new G();g.p.AddRange(source.vertices);g.uv.AddRange(source.uv);g.ids.AddRange(source.triangles);int originalTriangles=g.ids.Count/3;GunRooftop(g,w,d,h,lod);for(int i=g.ids.Count-3;i>=0;i-=3)if(Vector3.Cross(g.p[g.ids[i+1]]-g.p[g.ids[i]],g.p[g.ids[i+2]]-g.p[g.ids[i]]).sqrMagnitude<1e-12f)g.ids.RemoveRange(i,3);var mesh=g.Save(current.name,GunDir);filter.sharedMesh=mesh;PrefabUtility.RecordPrefabInstancePropertyModifications(filter);totals[lod]=mesh.triangles.Length/3;additions[lod]=totals[lod]-originalTriangles;foreach(var obj in loaded)UnityEngine.Object.DestroyImmediate(obj);}
root.GetComponent<LODGroup>().RecalculateBounds();PrefabUtility.RecordPrefabInstancePropertyModifications(root.GetComponent<LODGroup>());PrefabUtility.ApplyPrefabInstance(root,InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);var mat=AssetDatabase.LoadAssetAtPath<Material>(MaterialPath);if(ShaderUtil.ShaderHasError(mat.shader))throw new Exception("Billboard shader error");if(!atlasBytes.SequenceEqual(File.ReadAllBytes(Atlas)))throw new Exception("Atlas unexpectedly changed");var ctrl=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool was=ctrl.IsNight;float day=-1,night=-1;try{foreach(bool n in new[]{false,true}){ctrl.Apply(n);if(n)night=Shader.GetGlobalFloat("_GangstarNight");else day=Shader.GetGlobalFloat("_GangstarNight");var cp=root.transform.TransformPoint(new Vector3(w*.45f,5.1f,d/2+23));var target=root.transform.TransformPoint(new Vector3(0,h*.78f,d/2-1));GunCapture(ctrl,Tuple.Create(cp,Quaternion.LookRotation(target-cp)),"Gangfire-Rooftop-"+(n?"Night":"Day"));}}finally{ctrl.Apply(was);}EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/GangfireRooftop.txt","SUCCESS freestanding rooftop 3D lettering ONLY; title approximately14.87m wide x2.05m high, subtitle approximately12.25m wide x.80m high. Top3.525m above original roof; letter depth~.079m. White GANGFIRE and red GUNS HUNTING AMMO. No black backing panel or surrounding border. Lettering lowered0.6m and fixed with slim rear baseline rails, five roof posts, bolted base plates and three rear braces. Same hospital material and atlas, atlas bytes unchanged; combined into existing LOD meshes so additional renderers/material slots/realtime lights=0. Added triangles="+string.Join(",",additions)+" total triangles="+string.Join(",",totals)+". Day emission="+day+", night="+night+". Original facade, source transform and step colliders retained. Shader errors=0. Scene/prefab/assets saved. Device FPS unmeasured.");}
public static void BatchGangfireRoof(){EditorSceneManager.OpenScene("Assets/Scenes/Oasis/MobileOptimization/Gangstar City.unity");AddGunRooftop();}
